#!/usr/bin/env node
// Copy the entity renderer spec from the NxisAI MCP server into this repo, and regenerate src/harness/renderer-spec.ts from it.
//
// The spec (which archetype each schema.org type draws as, what each action is for and is called, the access labels)
// is generated by the MCP server and served to the NxisAI app's widgets. The harness draws the same cards on a site's
// own page, so it carries the same file twice: verbatim, as spec/renderer-spec.json (the snapshot a reviewer diffs
// against the server's copy), and as a module, src/harness/renderer-spec.ts, since the build has no JSON imports.
// test/renderer-spec.test.ts fails when the two disagree.
//
//   node scripts/sync-renderer-spec.mjs <path to the MCP server's renderer-spec.json>
//       copy it to spec/renderer-spec.json, then regenerate the module
//   node scripts/sync-renderer-spec.mjs
//       regenerate the module from spec/renderer-spec.json as it is
//   node scripts/sync-renderer-spec.mjs --check
//       exit 1, changing nothing, when the module is not what the snapshot generates
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const SNAPSHOT = fileURLToPath(new URL('../spec/renderer-spec.json', import.meta.url));
const MODULE = fileURLToPath(new URL('../src/harness/renderer-spec.ts', import.meta.url));

/** The keys a renderer spec must have; anything else is the wrong file. */
const REQUIRED = ['version', 'archetypes', 'actions', 'access', 'types'];

/** Parse a spec, or say why it isn't one. */
export function parseSpec(text, from = 'spec') {
  const spec = JSON.parse(text);
  for (const key of REQUIRED) if (!(key in spec)) throw new Error(`${from}: not a renderer spec, no "${key}"`);
  return spec;
}

/** The module's text for a spec: the one place its shape is decided, shared with the test. */
export function renderModule(spec) {
  return (
    `// Generated by scripts/sync-renderer-spec.mjs from spec/renderer-spec.json.\n` +
    `// Do not edit by hand: refresh with \`npm run sync:spec -- <path to renderer-spec.json>\`.\n` +
    `// Spec version ${spec.version}; schema.org ${spec.schemaVersion}.\n` +
    `/* eslint-disable */\n` +
    `export const RENDERER_SPEC = ${JSON.stringify(spec, null, 2)} as const;\n`
  );
}

function main(args) {
  const check = args.includes('--check');
  const from = args.find((a) => !a.startsWith('--'));
  try {
    if (from) {
      const text = readFileSync(from, 'utf8');
      parseSpec(text, from);
      if (check) throw new Error('--check takes no source file');
      writeFileSync(SNAPSHOT, text.endsWith('\n') ? text : text + '\n');
      console.log(`copied ${from} to ${SNAPSHOT}`);
    }
    const spec = parseSpec(readFileSync(SNAPSHOT, 'utf8'), SNAPSHOT);
    const out = renderModule(spec);
    if (check) {
      const current = readFileSync(MODULE, 'utf8');
      if (current !== out) {
        console.error(`${MODULE} is out of date with ${SNAPSHOT}: run node scripts/sync-renderer-spec.mjs`);
        process.exit(1);
      }
      console.log(`${MODULE} matches the snapshot (spec version ${spec.version})`);
      return;
    }
    writeFileSync(MODULE, out);
    console.log(`wrote ${MODULE}: spec version ${spec.version}, ${Object.keys(spec.types).length} types`);
  } catch (err) {
    console.error(err instanceof Error ? err.message : String(err));
    process.exit(1);
  }
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) main(process.argv.slice(2));
